        return 0.0

    if not alive_opps:
        return float(min(budget, 20.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    units = supply / WATER_REQ
    tight = units < 2.0
    very_tight = units < 1.5
    ample = units >= 2.0

    if hp <= 2 or no_water_days >= 2:
        bid = max(88.0, highest_prev + 2.5)
    elif hp <= 4 or no_water_days >= 1:
        if very_tight:
            bid = max(78.0, highest_prev + 1.5)
        else:
            bid = max(62.0, avg_prev + 2.0)
    else:
        if ample:
            if highest_prev >= 90:
                bid = 24.0
            elif highest_prev >= 75:
                bid = 31.0
            else:
                bid = 36.0
        else:
            if highest_prev >= 95:
                bid = 52.0
            elif highest_prev >= 75:
                bid = highest_prev + 1.2
            elif highest_prev >= 45:
                bid = max(48.0, highest_prev + 1.0)
            else:
                bid = 44.0

    if rich_aggressive >= 2 and hp > 4 and ample:
        bid *= 0.8
    if desperate_opp >= 2 and hp > 4 and very_tight:
        bid *= 0.9

    if day >= 8:
        if hp >= 6:
            bid *= 0.92
        else:
            bid *= 1.08

    if budget < DAILY_SALARY:
        bid = min(bid, budget * 0.82)
    else:
        bid = min(bid, budget * 0.68)

    bid = max(0.0, min(float(budget), float(bid)))
    return float(round(bid, 2))

