def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for k in opponents_status:
        o = opponents_status[k]
        if o.get('alive', False):
            alive_opps.append(o)

    # If no opponents alive, bid conservatively.
    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace only.
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = 0.0
    if len(prev_bids) >= 2:
        sorted_b = sorted(prev_bids, reverse=True)
        second_prev_bid = float(sorted_b[1])

    # Supply pressure: higher supply means easier win; lower supply means need more.
    # Map supply to a multiplier in [0.9, 1.2]
    if MAX_SUPPLY == MIN_SUPPLY:
        supply_mult = 1.0
    else:
        supply_mult = 0.9 + 0.3 * ((supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY))

    # Our urgency: if we are close to death, bid aggressively.
    # Use hp and no_water_days to infer risk.
    urgency = 0.0
    if hp <= 2:
        urgency += 0.8
    elif hp <= 5:
        urgency += 0.45
    else:
        urgency += 0.2

    # If we've already gone without water, increase urgency.
    urgency += min(0.6, 0.15 * max(0, no_water_days))

    # Opponent pressure: if someone bid very high yesterday, expect continued competition.
    opp_pressure = 0.0
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        opp_pressure = 0.9
    elif highest_prev_bid >= DAILY_SALARY * 0.6:
        opp_pressure = 0.6
    elif highest_prev_bid >= DAILY_SALARY * 0.35:
        opp_pressure = 0.35
    else:
        opp_pressure = 0.2

    # Base target bid: try to slightly outbid typical strong bids without overpaying.
    # If we have evidence of a strong leader, target around (second_prev_bid + small increment).
    target = 0.0
    if second_prev_bid > 0.0:
        target = second_prev_bid + 2.5
    else:
        # fallback to a fraction of daily salary
        target = DAILY_SALARY * (0.45 + 0.3 * opp_pressure)

    # Adjust with urgency and supply.
    target *= (1.0 + 0.6 * urgency)
    target *= supply_mult

    # Additional exploit: if highest_prev_bid is extremely high, avoid matching it exactly; instead bid just enough.
    if highest_prev_bid > 0:
        cap = highest_prev_bid * 0.92
        if target > cap:
            target = cap

    # Ensure we don't exceed budget.
    bid = max(0.0, min(budget, target))

    # If budget is tiny, still bid all-in.
    if budget <= DAILY_SALARY * 0.05:
        return max(0.0, budget)

    return bid
